// karaoke.js: karaoke with a character-by-character fill, drawn on the 2D compositor through window.overlayHook in
// core.js (crisp, above the paper grain). Font, sizes and colours come from STYLE (src/style.js, `./vf style <preset>`):
// sizes are measured glyph heights (kit/styles/_targets.json) — smaller than v10 of 挪威的森林 by the user's call.
// The bar sits around y ≈ 1024 and scales with the lyric size.
// Lines come from src/lyrics.js (LY, generated by `./vf lyrics assets/song.lrc --start=…`), title from SONG in config.js.
//
// LY = [[start, end, "line", opts?]]. opts.sing = seconds the line takes to sing (for the fill); opts.pun =
// { from, to, at }: at time `at`, the characters `from` get a painted strike and `to` pops in above them (a visual
// joke on a lyric); opts.hold = seconds the line stays up after it ends, lifted above the next line.
// Lines that butt against each other keep the bar up (an empty bar flashing between lines was a v2 defect).
const KFONT = STYLE.css, KS = STYLE.canvas, KC = STYLE.colors, KZ = KS.karaoke / 64;   // KZ scales the bar geometry
window.EXTRA_FONTS = [[`${KS.karaoke}px ${KFONT}`, LY.map(l => l[2] + ((l[3] && l[3].pun && l[3].pun.to) || '')).join('')]];

window.EXTRA_FONTS[0][1] += SONG.title + SONG.artist;
function openingTitle(c, t) {   // 0.3–3.0 s: song and singer, so a scrolling viewer knows what this is
  if (PROJECT.noTitle) return;   // the vertical layout carries its own, larger title
  const a = clamp((t - .3) / .5) * (1 - clamp((t - 2.6) / .5)); if (a <= 0) return;
  c.save(); c.globalAlpha = a; c.textAlign = 'center'; c.textBaseline = 'middle';
  c.shadowColor = 'rgba(10,12,40,.75)'; c.shadowBlur = 24;
  c.font = `${KS.openTitle}px ${KFONT}`; c.fillStyle = KC.title; c.fillText(SONG.title, 960, 220 + 12 * (1 - a));
  c.font = `${KS.openArtist}px ${KFONT}`; c.fillStyle = KC.artist; c.fillText([...SONG.artist].join(' '), 960, 220 + KS.openTitle * .9 + 12 * (1 - a));
  c.restore();
}
// Effective end of each line: a gap under 1 s is bridged (the bar stays up and only the words change — an empty bar
// flashing between lines was a 挪威的森林 v5 defect), and the last line stays up to the end of the video.
const LYEND = LY.map((l, k) => k + 1 < LY.length && LY[k + 1][0] < DUR ? (LY[k + 1][0] - l[1] < 1 ? LY[k + 1][0] : l[1]) : DUR);
window.overlayHook = (c, t) => {
  openingTitle(c, t);
  const i = LY.findIndex((l, k) => t >= l[0] && t < LYEND[k]);
  // a line with opts.hold stays up after its time, lifted and shrunk above the next one (two-row KTV style)
  const P = LY.find(l => l[3] && l[3].hold && t >= l[1] && t < l[1] + l[3].hold);
  if (P) { const a = t - P[1], k = ease(a / .15); kLine(c, P, t, 1024 - 108 * KZ * k, 1 - .3 * k, 1 - ease((a - (P[3].hold - .3)) / .3), true); }
  if (i >= 0) kLine(c, LY[i], t, 1024, 1, 1, false);
};
function kLine(c, L, t, y, sc, alpha, held) {
  const [a, b, txt, opt = {}] = L;
  // lines that butt against each other keep the bar up instead of collapsing and regrowing (an empty bar flashed between them)
  const k0 = LY.indexOf(L), prevJoin = k0 > 0 && LYEND[k0 - 1] >= a, nextJoin = k0 + 1 < LY.length && LYEND[k0] >= LY[k0 + 1][0];
  const grow = held ? 1 : (prevJoin ? 1 : easeOut((t - a) / .14));
  const be = LYEND[k0], last = be >= DUR;
  const endFade = held || opt.hold || nextJoin || last ? 1 : 1 - ease((t - (be - .14)) / .14);   // the line fades out whole, bar and text together
  if (grow < .02 || alpha <= .01 || endFade <= .01) return;
  alpha *= endFade;
  c.save(); c.globalAlpha = alpha; c.translate(960, y); c.scale(sc, sc); c.translate(-960, -y);
  c.font = `${KS.karaoke}px ${KFONT}`; c.textBaseline = 'middle'; c.textAlign = 'left';
  const total = c.measureText(txt).width;
  // the bar: a ragged ink lozenge that grows from the centre and boils with the linework
  const z = KZ, w = (total + 120 * z) * grow, x0 = 960 - w / 2, y0 = y - 48 * z, r = n => (hash(BOILN * 13 + n) * 8 - 4) * z;
  c.globalAlpha = .86 * alpha; c.fillStyle = KC.bar; c.beginPath();
  c.moveTo(x0 + r(1), y0 + r(2)); c.lineTo(x0 + w / 2, y0 - 5 * z + r(3)); c.lineTo(x0 + w + r(4), y0 + r(5));
  c.lineTo(x0 + w + 16 * z, y0 + 46 * z); c.lineTo(x0 + w + r(6), y0 + 92 * z + r(7)); c.lineTo(x0 + w / 2, y0 + 96 * z + r(8));
  c.lineTo(x0 + r(9), y0 + 92 * z + r(10)); c.lineTo(x0 - 16 * z, y0 + 46 * z); c.closePath(); c.fill();
  c.globalAlpha = alpha;
  const ta = held || prevJoin ? 1 : clamp((t - a) / .12), textA = ta;
  if (grow > .15) {
    c.globalAlpha = alpha * textA;
    // characters fill left to right as they're sung (opt.sing = how long the line takes to sing)
    const n = [...txt].length, singDur = opt.sing ?? Math.min((b - a) * .85, n * .3), f = held ? 1 : clamp((t - a) / singDur);
    const x = 960 - total / 2;
    c.fillStyle = KC.base; c.fillText(txt, x, y);
    c.save(); c.beginPath(); c.rect(x - 2, y - 50 * KZ, total * f + 2, 100 * KZ); c.clip(); c.fillStyle = KC.fill; c.fillText(txt, x, y); c.restore();
    if (opt.pun && t > opt.pun.at) pun(c, txt, x, y, opt.pun, t - opt.pun.at);
  }
  c.restore();
}

// Strike through `from` with a red brush stroke, then pop `to` in above it, tilted, in gold with an ink shadow.
function pun(c, txt, x, y, p, age) {
  const i = txt.indexOf(p.from); if (i < 0) return;
  const px = x + c.measureText(txt.slice(0, i)).width, pw = c.measureText(p.from).width;
  const k = easeOut(age / .25);
  c.save(); c.strokeStyle = '#D8394E'; c.lineCap = 'round'; c.lineWidth = 9;
  c.beginPath(); c.moveTo(px - 8, y + 6);
  for (let j = 1; j <= 8; j++) { const q = j / 8 * k; c.lineTo(px - 8 + (pw + 16) * q, y + 6 - 12 * q + Math.sin(j * 1.7) * 2); }
  c.stroke(); c.restore();
  const pop = backOut(clamp((age - .2) / .35)); if (pop <= .01) return;
  c.save(); c.translate(px + pw / 2 + 10, y - 88 * KZ); c.rotate(-.12 + Math.sin(age * 14) * .04 * Math.exp(-age * 2)); c.scale(pop, pop);
  c.font = `${KS.pun}px ${KFONT}`; c.textAlign = 'center'; c.textBaseline = 'middle';
  c.lineJoin = 'round'; c.lineWidth = KS.pun * .15; c.strokeStyle = KC.bar; c.strokeText(p.to, 0, 0);
  c.fillStyle = KC.bar; c.fillText(p.to, 5, 6);
  c.fillStyle = KC.pun; c.fillText(p.to, 0, 0);
  c.restore();
}
